    for(int i = 0; i < nFiles; i++){
        fwrite(fileNames[i], sizeof(char), strlen(fileNames[i]) + 1, f);
        fwrite(&fileSizes[i], sizeof(int), 1, f);
    }
    fclose(f);
    free(fileSizes);
    return EXIT_SUCCESS;
}

